function imageName(mon) {
  return mon.imageId || mon.id.toLowerCase();
}

function createTypeBadges(types) {
  return types
    .map(type => `<span class="type-badge type-${type.toLowerCase()}">${type}</span>`)
    .join("");
}

function createSpriteImage(mon, suffix, label) {
  const file = `images/pokemon/${imageName(mon)}-${suffix}.png`;

  return `
    <div class="sprite-box">
      <img
        src="${file}"
        alt="${mon.name} ${label}"
        loading="lazy"
        onerror="this.style.display='none'; this.nextElementSibling.style.display='block';"
      >
      <span class="sprite-placeholder">${label}</span>
    </div>
  `;
}

function createPokemonCard(mon) {
  const card = document.createElement("article");
  card.className = "dex-card";

  card.innerHTML = `
    <div class="dex-card-header">
      <span class="dex-number">
        ${mon.isRegionalForm ? "Regional Form" : `#${mon.dex}`}
      </span>
      <h3>${mon.name}</h3>
    </div>

    <div class="type-list">
      ${createTypeBadges(mon.types)}
    </div>

    <p class="dex-category">${mon.category}</p>
    <p class="dex-description">${mon.description}</p>

    <div class="sprite-gallery">
      ${createSpriteImage(mon, "front", "Front Sprite")}
      ${createSpriteImage(mon, "back", "Back Sprite")}
      ${createSpriteImage(mon, "icon", "Icon")}
      ${createSpriteImage(mon, "overworld", "Overworld Sprite")}
      ${createSpriteImage(mon, "footprint", "Footprint")}
    </div>
  `;

  return card;
}

function renderCards(grid, list, emptyMessage) {
  if (!grid) {
    return;
  }

  grid.innerHTML = "";

  if (list.length === 0) {
    grid.innerHTML = `<p class="no-results">${emptyMessage}</p>`;
    return;
  }

  list.forEach(mon => {
    grid.appendChild(createPokemonCard(mon));
  });
}

function ensureRegionalFormsSection() {
  let section = document.getElementById("regionalFormsSection");

  if (section) {
    return section.querySelector("#regionalFormsGrid");
  }

  const mainGrid = document.getElementById("pokedexGrid");

  if (!mainGrid) {
    return null;
  }

  section = document.createElement("section");
  section.id = "regionalFormsSection";

  section.innerHTML = `
    <h2>Inflamous Regional Forms</h2>
    <p>Custom regional forms detected from pokemon_forms.txt.</p>
    <div id="regionalFormsGrid" class="dex-grid"></div>
  `;

  const mainSection = mainGrid.closest("section");

  if (mainSection && mainSection.parentNode) {
    mainSection.parentNode.insertBefore(section, mainSection.nextSibling);
  }

  return section.querySelector("#regionalFormsGrid");
}

function matchesSearch(mon, query) {
  return [
    mon.dex,
    mon.id,
    mon.name,
    ...mon.types,
    mon.category,
    mon.description,
    mon.isRegionalForm ? "regional form" : "fakemon"
  ]
    .join(" ")
    .toLowerCase()
    .includes(query);
}

function renderAll(query = "") {
  const mainGrid = document.getElementById("pokedexGrid");
  const regionalGrid = ensureRegionalFormsSection();

  const filteredMain = pokemonData.filter(mon => matchesSearch(mon, query));
  const filteredRegional = regionalFormData.filter(mon => matchesSearch(mon, query));

  renderCards(mainGrid, filteredMain, "No Pok\u00E9mon matched your search.");
  renderCards(regionalGrid, filteredRegional, "No regional forms matched your search.");
}

function setupSearch() {
  const searchBox = document.getElementById("dexSearch");

  if (!searchBox) {
    return;
  }

  searchBox.addEventListener("input", () => {
    renderAll(searchBox.value.trim().toLowerCase());
  });
}

document.addEventListener("DOMContentLoaded", () => {
  renderAll();
  setupSearch();
});